INSERT INTO room_types (id, name, slug, description, image_url, visible, created_at, updated_at) VALUES ('262238d8-c601-1ce9-a8ae-18359ef6b967', 'Phòng khách', 'phong-khach', 'Không gian dành cho sinh hoạt, tiếp khách và thư giãn với các nội thất phục vụ nhu cầu sử dụng hằng ngày.', 'https://res.cloudinary.com/dhqmtiaex/image/upload/v1785742022/furnisight/catalog/living-room_ss5zrv.jpg', True, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO room_types (id, name, slug, description, image_url, visible, created_at, updated_at) VALUES ('88ac8de7-9776-db6f-4cb4-99d4336eeb71', 'Phòng tắm', 'phong-tam', 'Không gian phục vụ nhu cầu vệ sinh và chăm sóc cá nhân với các thiết bị và nội thất chuyên dụng.', 'https://res.cloudinary.com/dhqmtiaex/image/upload/v1785742042/furnisight/catalog/bathroom_v4b1fu.jpg', True, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO room_types (id, name, slug, description, image_url, visible, created_at, updated_at) VALUES ('0be83d7a-ebbe-ce02-72a0-1228a04bc054', 'Phòng bếp', 'phong-bep', 'Không gian phục vụ việc nấu nướng, ăn uống và lưu trữ dụng cụ, được thiết kế để đảm bảo tính tiện dụng.', 'https://res.cloudinary.com/dhqmtiaex/image/upload/v1785742157/furnisight/catalog/kitchen_rdbjqr.jpg', True, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO room_types (id, name, slug, description, image_url, visible, created_at, updated_at) VALUES ('b58eccfb-66b2-177f-89e0-6cd52ee4d85b', 'Phòng ngủ', 'phong-ngu', 'Không gian nghỉ ngơi, thư giãn được bố trí các nội thất nhằm mang lại sự thoải mái và tiện nghi.', 'https://res.cloudinary.com/dhqmtiaex/image/upload/v1785742196/furnisight/catalog/bedroom_poj6ru.jpg', True, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('2a637134-4b4f-bf38-84ad-ae509c07e96f', 'Ghế ăn', 'ghe-an', NULL, '0be83d7a-ebbe-ce02-72a0-1228a04bc054', '', 0, NULL, True, 'Ghế ăn được thiết kế cho khu vực bàn ăn, mang lại sự thoải mái và phù hợp với nhiều phong cách nội thất.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('12805f51-f53f-e737-b3e5-7a5b9d5e45b8', 'Bàn ăn', 'ban-an', NULL, '0be83d7a-ebbe-ce02-72a0-1228a04bc054', '', 0, NULL, True, 'Bàn ăn dành cho phòng bếp hoặc phòng ăn, có nhiều kiểu dáng và kích thước đáp ứng nhu cầu sử dụng của gia đình.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('9fb3176e-46fb-e87f-9f41-4c6b2604a203', 'Ghế ăn có tay vịn', 'ghe-an-co-tay-vin', NULL, '0be83d7a-ebbe-ce02-72a0-1228a04bc054', '', 0, NULL, True, 'Ghế ăn có tay vịn giúp tăng khả năng nâng đỡ và sự thoải mái, phù hợp với không gian phòng ăn gia đình hoặc khu vực tiếp khách.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('f8ee110b-1a6c-6fb1-275a-2c30eef4f211', 'Giường và đầu giường', 'giuong-va-dau-giuong', NULL, 'b58eccfb-66b2-177f-89e0-6cd52ee4d85b', '', 0, NULL, True, 'Bao gồm các mẫu giường và đầu giường với nhiều kiểu dáng, kích thước và phong cách thiết kế, mang đến không gian nghỉ ngơi thoải mái và nâng cao tính thẩm mỹ cho phòng ngủ.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('45ee3b7d-83b4-294b-fce1-7e855b62cf96', 'Tủ đầu giường', 'tu-dau-giuong', NULL, 'b58eccfb-66b2-177f-89e0-6cd52ee4d85b', '', 0, NULL, True, 'Tủ đầu giường được thiết kế nhỏ gọn, cung cấp không gian lưu trữ tiện lợi cho các vật dụng cá nhân và tạo sự đồng bộ với nội thất phòng ngủ.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('ad713bfe-5793-e098-d2bb-ccee0961566b', 'Giường bệt', 'giuong-bet', NULL, 'b58eccfb-66b2-177f-89e0-6cd52ee4d85b', '', 0, NULL, True, 'Giường bệt có thiết kế thấp, hiện đại và tối giản, phù hợp với nhiều phong cách nội thất, mang lại không gian nghỉ ngơi rộng rãi và thoải mái.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('043cc05c-6627-b230-5b5b-71d9426f2d77', 'Tủ ngăn kéo', 'tu-ngan-keo', NULL, 'b58eccfb-66b2-177f-89e0-6cd52ee4d85b', '', 0, NULL, True, 'Tủ ngăn kéo cung cấp không gian lưu trữ quần áo và đồ dùng cá nhân, đồng thời góp phần tạo nên không gian phòng ngủ gọn gàng và ngăn nắp.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('9f78ae93-d859-0893-bd85-58d2d1f34c43', 'Giường canopy', 'giuong-canopy', NULL, 'b58eccfb-66b2-177f-89e0-6cd52ee4d85b', '', 0, NULL, True, 'Giường canopy nổi bật với khung bao quanh phía trên, tạo điểm nhấn sang trọng và ấn tượng, phù hợp với các không gian phòng ngủ mang phong cách hiện đại hoặc cổ điển.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('16bc894b-0e9b-583e-ad23-dafb43200b62', 'Bàn phụ', 'ban-phu', NULL, '262238d8-c601-1ce9-a8ae-18359ef6b967', '', 0, NULL, True, 'Bàn phụ có kích thước nhỏ gọn, thường được đặt cạnh sofa hoặc ghế bành để hỗ trợ đặt đồ dùng và tạo điểm nhấn cho không gian phòng khách.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('b5abeb51-d655-c2dd-b795-c35e6b9a3c8f', 'Bàn console', 'ban-console', NULL, '262238d8-c601-1ce9-a8ae-18359ef6b967', '', 0, NULL, True, 'Bàn console có kiểu dáng dài và hẹp, thường được đặt sát tường, sau sofa hoặc tại khu vực lối vào để trang trí và hỗ trợ đặt vật dụng.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('40abee88-08e0-2eb3-6322-2a378cc12436', 'Cây trang trí', 'cay-trang-tri', NULL, '262238d8-c601-1ce9-a8ae-18359ef6b967', '', 0, NULL, True, 'Cây và chậu cây trang trí giúp bổ sung mảng xanh, tạo điểm nhấn tự nhiên và làm mềm không gian phòng khách.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('0f1009d0-7040-f0e0-8a49-15c9a15aa1ad', 'Ghế bành', 'ghe-banh', NULL, '262238d8-c601-1ce9-a8ae-18359ef6b967', '', 0, NULL, True, 'Ghế bành và ghế điểm nhấn có tay vịn, thường được bố trí trong phòng khách, góc đọc sách hoặc khu vực thư giãn.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('18b69b70-6d60-230a-bf07-7b0261a4eea7', 'Ghế băng', 'ghe-bang', NULL, 'b58eccfb-66b2-177f-89e0-6cd52ee4d85b', '', 0, NULL, True, 'Ghế băng phòng ngủ thường được đặt cuối giường hoặc tại góc thay đồ, vừa tạo điểm nhấn thẩm mỹ vừa hỗ trợ ngồi nghỉ và đặt vật dụng.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('1d159325-75ed-eb7d-4028-166180fcaa43', 'Kệ lưu trữ phòng tắm', 'ke-luu-tru-phong-tam', NULL, '88ac8de7-9776-db6f-4cb4-99d4336eeb71', '', 0, NULL, True, 'Kệ lưu trữ phòng tắm cung cấp không gian sắp xếp khăn, mỹ phẩm và đồ dùng cá nhân, đồng thời tận dụng hiệu quả diện tích theo chiều cao.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('45e193fd-9db3-2a16-e4d3-1b9191568844', 'Giỏ đựng đồ giặt', 'gio-dung-do-giat', NULL, '88ac8de7-9776-db6f-4cb4-99d4336eeb71', '', 0, NULL, True, 'Giỏ đựng đồ giặt giúp thu gom quần áo gọn gàng, hạn chế đồ dùng bừa bộn và góp phần duy trì không gian phòng tắm sạch sẽ.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('f771c92b-b11a-f2f6-90c3-78b8e25b2539', 'Giá treo khăn', 'gia-treo-khan', NULL, '88ac8de7-9776-db6f-4cb4-99d4336eeb71', '', 0, NULL, True, 'Giá treo khăn hỗ trợ phơi và sắp xếp khăn tắm theo nhiều tầng, phù hợp với phòng tắm cần giải pháp lưu trữ gọn nhẹ và linh hoạt.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('5cb87d5b-6675-31f5-4dba-afed822645a2', 'Giỏ lưu trữ phòng tắm', 'gio-luu-tru-phong-tam', NULL, '88ac8de7-9776-db6f-4cb4-99d4336eeb71', '', 0, NULL, True, 'Giỏ lưu trữ phòng tắm hỗ trợ sắp xếp khăn, đồ dùng cá nhân hoặc vật dụng trang trí, đồng thời tạo điểm nhấn tự nhiên cho không gian.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, name, slug, parent_id, room_type_id, path, product_count, icon_url, visible, description, image_url, created_at, updated_at) VALUES ('698bddc8-062b-53a8-90fb-843da9f8b89a', 'Phụ kiện phòng tắm', 'phu-kien-phong-tam', NULL, '88ac8de7-9776-db6f-4cb4-99d4336eeb71', '', 0, NULL, True, 'Phụ kiện phòng tắm gồm các vật dụng hỗ trợ sắp xếp và sử dụng hằng ngày như giá đỡ giấy, khay đựng đồ và các phụ kiện đặt trên mặt bàn.', NULL, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('fd342f1c-932d-1693-4cd9-13d2ac1ca354', '2a637134-4b4f-bf38-84ad-ae509c07e96f', 'Ghế ăn không tay vịn Norrie', 'ghe-an-khong-tay-vin-norrie', 'DC-NOR', 'Ghế ăn Norrie không tay vịn do Caleb Zipperer thiết kế, nổi bật với khung gỗ sồi đỏ tiện thanh mảnh, chi tiết hoàn thiện màu đồng thau và phần đệm ngồi êm ái. Thiết kế góc cạnh nhưng tinh gọn giúp sản phẩm phù hợp với nhiều không gian phòng ăn hiện đại.', 'ACTIVE', 17068700.0, '["\"Thiết kế độc quyền bởi Caleb Zipperer\",", "\"Khung gỗ sồi đỏ đạt chứng nhận FSC\",", "\"Khung được tiện tạo đường nét thanh mảnh\",", "\"Chi tiết hoàn thiện màu đồng thau\",", "\"Đệm mút mật độ cao tạo cảm giác êm ái\",", "\"Có nhiều lựa chọn vải và màu sắc\""]', '{"details": "Nhà thiết kế: Caleb Zipperer\nLoại sản phẩm: Ghế ăn không tay vịn\nChất liệu khung: Gỗ sồi đỏ đạt chứng nhận FSC\nKết cấu khung: Gỗ được tiện tạo đường nét thanh mảnh\nChi tiết hoàn thiện: Màu đồng thau\nCấu tạo đệm: Mút mật độ cao\nChiều cao mặt ngồi: 45.72 cm\nChiều rộng mặt ngồi: 48.90 cm\nĐộ sâu mặt ngồi: 46.99 cm\nĐặc điểm vật liệu: Sắc độ, mắt gỗ và dấu vân tự nhiên khác nhau trên từng sản phẩm\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Thấm hút ngay khi chất lỏng bị đổ bằng khăn sạch; chỉ vệ sinh điểm bằng chất tẩy vết bẩn không chứa nước; với vết bẩn cứng đầu nên sử dụng dịch vụ vệ sinh bọc ghế chuyên nghiệp"}', NULL, 62.87, 55.25, 79.38, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('4ad501af-4734-bcf7-9598-6c17b3fa4194', '2a637134-4b4f-bf38-84ad-ae509c07e96f', 'Ghế ăn Wesler có bánh xe', 'ghe-an-wesler-co-banh-xe', 'DC-WES', 'Ghế ăn Wesler có bánh xe do Aurélien Barbry thiết kế, được bọc vải toàn bộ với phần đệm dày tạo cảm giác êm ái. Đế ghế được làm lõm và tích hợp bánh xe ẩn, giúp người dùng dễ dàng di chuyển mà vẫn giữ được kiểu dáng gọn gàng, hiện đại.', 'ACTIVE', 13123700.0, '["\"Thiết kế độc quyền bởi Aurélien Barbry\",", "\"Bọc vải toàn bộ tạo vẻ ngoài liền mạch\",", "\"Khung gỗ kỹ thuật đạt chứng nhận FSC\",", "\"Đệm mút mật độ cao bọc sợi polyester\",", "\"Bánh xe ẩn giúp di chuyển linh hoạt\",", "\"Vải hiệu suất có khả năng hạn chế bám bẩn và phai màu\",", "\"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: Aurélien Barbry\nChất liệu khung: Gỗ kỹ thuật nguyên khối đạt chứng nhận FSC\nCấu tạo đệm: Mút mật độ cao bọc sợi polyester\nCơ chế di chuyển: Bánh xe ẩn tại phần đế\nĐặc tính vải: Lớp hoàn thiện bảo vệ giúp hạn chế bám bẩn và phai màu\nChiều cao tay vịn: 64.14 cm\nChiều cao mặt ngồi: 49.53 cm\nChiều rộng mặt ngồi: 52.07 cm\nĐộ sâu mặt ngồi: 50.80 cm\nCấp độ sử dụng: Đạt tiêu chuẩn nội thất thương mại\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Thấm hút ngay khi chất lỏng bị đổ bằng khăn sạch; chỉ vệ sinh điểm bằng chất tẩy vết bẩn không chứa nước; với vết bẩn cứng đầu nên sử dụng dịch vụ vệ sinh bọc ghế chuyên nghiệp"}', 20.87, 57.79, 59.69, 76.2, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('2cb181ec-51e0-6672-03ca-b214edba7074', '2a637134-4b4f-bf38-84ad-ae509c07e96f', 'Ghế ăn Norrie có tay vịn', 'ghe-an-co-tay-vin-norrie', 'DAC-NOR', 'Ghế ăn Norrie có tay vịn do Caleb Zipperer thiết kế, sử dụng khung gỗ sồi đỏ tiện mảnh kết hợp chi tiết màu đồng thau. Tay vịn và phần đệm ngồi giúp tăng khả năng nâng đỡ, phù hợp cho các bữa ăn dài hoặc không gian tiếp khách.', 'ACTIVE', 18383700.0, '["\"Thiết kế độc quyền bởi Caleb Zipperer\",", "\"Khung gỗ sồi đỏ đạt chứng nhận FSC\",", "\"Khung tiện thanh mảnh với đường nét góc cạnh\",", "\"Chi tiết hoàn thiện màu đồng thau\",", "\"Đệm mút mật độ cao tạo sự thoải mái và nâng đỡ\",", "\"Có nhiều lựa chọn vải bọc\""]', '{"details": "Nhà thiết kế: Caleb Zipperer\nLoại sản phẩm: Ghế ăn có tay vịn\nChất liệu khung: Gỗ sồi đỏ đạt chứng nhận FSC\nKết cấu khung: Gỗ được tiện tạo đường nét thanh mảnh\nChi tiết hoàn thiện: Màu đồng thau\nCấu tạo đệm: Mút mật độ cao\nChiều cao tay vịn: 62.87 cm\nChiều cao mặt ngồi: 45.72 cm\nChiều rộng mặt ngồi: 48.26 cm\nĐộ sâu mặt ngồi: 46.99 cm\nĐặc điểm vật liệu: Sắc độ, mắt gỗ và dấu vân tự nhiên khác nhau trên từng sản phẩm\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Thấm hút ngay khi chất lỏng bị đổ bằng khăn sạch; chỉ vệ sinh điểm bằng chất tẩy vết bẩn không chứa nước; với vết bẩn cứng đầu nên sử dụng dịch vụ vệ sinh bọc ghế chuyên nghiệp"}', 10.89, 62.87, 55.25, 79.38, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('b4205fc2-9983-37f7-35c0-e6d2cc9b9066', '12805f51-f53f-e737-b3e5-7a5b9d5e45b8', 'Bàn ăn hình chữ nhật Davison', 'ban-an-hinh-chu-nhat-davison', 'DT-DAV', 'Bàn ăn Davison 108 inch do Studio ANANSI thiết kế, sở hữu mặt bàn rộng, các góc bo mềm và hai chân đế dạng trụ có rãnh dọc. Kết cấu gỗ phủ veneer sồi được sấy lò giúp hạn chế cong vênh, phù hợp cho không gian phòng ăn lớn với sức chứa tối đa tám người.', 'ACTIVE', 65723700.0, '["\"Thiết kế độc quyền bởi Studio ANANSI\",", "\"Mặt bàn chữ nhật dài 108 inch, sức chứa tối đa 8 người\",", "\"Hai chân đế dạng trụ với chi tiết rãnh dọc\",", "\"Các góc bo mềm tạo kiểu dáng hiện đại\",", "\"Gỗ phủ veneer sồi đạt chứng nhận FSC\",", "\"Gỗ được sấy lò nhằm hạn chế cong vênh\",", "\"Sản xuất tại Indonesia\""]', '{"details": "Nhà thiết kế: Studio ANANSI\nChất liệu gỗ: Gỗ kỹ thuật đạt chứng nhận FSC phủ veneer sồi\nXử lý vật liệu: Gỗ được sấy lò nhằm tăng độ ổn định và hạn chế cong vênh\nKết cấu chân bàn: Hai chân đế dạng trụ có rãnh dọc\nSức chứa: Tối đa 8 người\nKhoảng cách từ sàn đến yếm bàn: 71.12 cm\nĐặc điểm vật liệu: Sắc độ, mắt gỗ và dấu vân tự nhiên khác nhau trên từng sản phẩm\nXuất xứ: Indonesia\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm khô; không dùng chất tẩy rửa có tính mài mòn; tránh nhiệt và chất lỏng; nên dùng miếng lót ly; lau ngay khi chất lỏng bị đổ"}', 158.94, 116.84, 274.32, 74.93, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('828f2617-6afa-d295-5035-5cc16a2d4c78', '12805f51-f53f-e737-b3e5-7a5b9d5e45b8', 'Bàn bistro tròn Rio 42 inch', 'ban-bistro-tron-rio-42-inch', 'DT-RIO', 'Bàn bistro tròn Rio 42 inch do Studio ANANSI thiết kế, kết hợp mặt đá onyx đánh bóng với khung gỗ tông óc chó ấm. Các biến đổi tự nhiên về sắc độ và đường vân đá tạo nên bề mặt riêng biệt cho từng sản phẩm. Kích thước bàn phù hợp cho tối đa bốn người.', 'ACTIVE', 70983700.0, '["\"Thiết kế độc quyền bởi Studio ANANSI\",", "\"Mặt bàn đá onyx đánh bóng với đường vân tự nhiên\",", "\"Chân đế gỗ mahogany phủ veneer óc chó đạt chứng nhận FSC\",", "\"Bàn tròn đường kính 42 inch, phù hợp tối đa 4 người\",", "\"Mỗi sản phẩm có sắc độ và đường vân đá riêng\",", "\"Sản xuất tại Indonesia\""]', '{"details": "Nhà thiết kế: Studio ANANSI\nChất liệu mặt bàn: Đá onyx đánh bóng\nChất liệu chân đế: Gỗ mahogany đạt chứng nhận FSC phủ veneer óc chó\nSức chứa: Tối đa 4 người\nĐặc điểm vật liệu: Màu sắc và đường vân onyx khác nhau trên từng sản phẩm; sắc độ, mắt gỗ và dấu vân tự nhiên có thể khác nhau\nXuất xứ: Indonesia\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm khô; không dùng chất tẩy rửa có tính mài mòn; tránh nhiệt và chất lỏng; nên dùng miếng lót ly; lau ngay khi chất lỏng bị đổ; đá tự nhiên có độ xốp và dễ bám bẩn"}', NULL, 106.68, 106.68, 76.2, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('ad26085e-bd71-37a2-0dd0-a55d3329d296', '9fb3176e-46fb-e87f-9f41-4c6b2604a203', 'Ghế ăn Arlo có tay vịn', 'ghe-an-arlo-co-tay-vin', 'DAC-AR', 'Ghế ăn Arlo có tay vịn sở hữu thiết kế hiện đại với đường nét thanh lịch và phần tựa lưng cong nhẹ, mang lại cảm giác thoải mái khi sử dụng. Sản phẩm phù hợp với nhiều phong cách nội thất, tạo điểm nhấn sang trọng cho không gian phòng ăn của gia đình hoặc khu vực tiếp khách.', 'ACTIVE', 11808700.0, '["\"Thiết kế hiện đại với đường nét thanh lịch\", \"Tựa lưng cong nhẹ tạo cảm giác thoải mái\", \"Khung ghế chắc chắn và bền bỉ\", \"Đệm ngồi dày, mang lại cảm giác êm ái\", \"Chi tiết hoàn thiện tinh tế\", \"Phù hợp với nhiều phong cách nội thất\", \"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: Brett Beldock\nChất liệu khung: Gỗ sồi nguyên khối đạt chứng nhận FSC\nCấu tạo đệm: Mút mật độ cao bọc sợi polyester\nChi tiết trang trí: Đinh bọc hoàn thiện màu đồng cổ\nChiều cao tay vịn: 66.04 cm\nChiều cao mặt ngồi: 48.26 cm\nChiều rộng mặt ngồi: 50.80 cm\nĐộ sâu mặt ngồi: 48.26 cm\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Thấm hút ngay khi chất lỏng bị đổ bằng khăn sạch; chỉ vệ sinh điểm bằng chất tẩy vết bẩn không chứa nước; với vết bẩn cứng đầu nên sử dụng dịch vụ vệ sinh bọc ghế chuyên nghiệp"}', 6.99, 54.61, 58.42, 76.2, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('07a2ea2e-c300-e1b2-56ce-95d1f26a4d47', '9fb3176e-46fb-e87f-9f41-4c6b2604a203', 'Ghế ăn Carson có tay vịn', 'ghe-an-carson-co-tay-vin', 'DAC-CAR', 'Ghế ăn Carson có tay vịn sở hữu thiết kế hiện đại với đường nét tinh tế, phần tựa lưng bo cong và đệm ngồi êm ái, mang đến sự thoải mái trong suốt quá trình sử dụng. Sản phẩm phù hợp với nhiều phong cách nội thất, tạo điểm nhấn sang trọng cho không gian phòng ăn gia đình hoặc khu vực tiếp khách.', 'ACTIVE', 14438700.0, '["\"Thiết kế hiện đại với đường nét tinh tế\",", "\"Tựa lưng bo cong tạo cảm giác thoải mái\",", "\"Khung ghế chắc chắn và bền bỉ\",", "\"Đệm ngồi dày, mang lại cảm giác êm ái\",", "\"Thanh giằng kim loại tăng độ ổn định cho khung ghế\",", "\"Phù hợp với nhiều phong cách nội thất\",", "\"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: Studio ANANSI\nChất liệu khung: Gỗ sồi nguyên khối đạt chứng nhận FSC\nCấu tạo đệm: Mút mật độ cao bọc sợi polyester\nChi tiết kết cấu: Thanh giằng kim loại hoàn thiện màu đồng thau cổ\nĐặc tính vải: Lớp hoàn thiện bảo vệ giúp hạn chế bám bẩn và phai màu\nChiều cao tay vịn: 64.77 cm\nChiều cao mặt ngồi: 48.26 cm\nChiều rộng mặt ngồi: 48.26 cm\nĐộ sâu mặt ngồi: 48.26 cm\nXuất xứ: Việt Nam"}', 15.0, 58.0, 62.0, 85.0, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('4a4c0c70-0e62-59f8-b1d9-f2dc44ed95d5', 'ad713bfe-5793-e098-d2bb-ccee0961566b', 'Giường bệt Andes cỡ Queen kèm tủ đầu giường', 'giuong-bet-andes-kem-tu-dau-giuong', 'BED-AND', 'Giường bệt Andes cỡ Queen do Mark Daniel của Slate Design thiết kế, tích hợp hai tủ đầu giường ở phần đầu giường, mỗi bên gồm một kệ rộng để sách và một kệ hẹp có lỗ đi dây kín đáo cho đèn, điện thoại hoặc đồng hồ. Khung bệ siêu thấp vươn ra trên các chân góc, trong khi nệm nằm ngang bằng với bệ và che kín hệ thanh đỡ. Sản phẩm có hai lựa chọn hoàn thiện gồm veneer Acacia tự nhiên và veneer sồi trắng Mỹ xử lý đen.', 'ACTIVE', 21013700.0, '["\"Thiết kế độc quyền bởi Mark Daniel của Slate Design\",", "\"Tích hợp hai tủ đầu giường, mỗi bên có hai kệ\",", "\"Kệ hẹp có lỗ đi dây kín đáo cho thiết bị điện tử\",", "\"Khung bệ siêu thấp tạo cảm giác rộng và thoáng\",", "\"Nệm nằm ngang bằng với bệ, che kín hệ thanh đỡ\",", "\"Chỉ sử dụng với nệm, không cần lò xo hộp\",", "\"Có hai lựa chọn hoàn thiện Acacia và đen ebonized\",", "\"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: Mark Daniel của Slate Design\nKích thước nệm: Queen\nKiểu giường: Giường bệt tích hợp tủ đầu giường\nTủ đầu giường: Hai kệ mỗi bên; kệ trên có lỗ luồn dây điện\nKết cấu: Bệ giường siêu thấp nhô ra khỏi phần chân đế\nYêu cầu sử dụng: Dùng trực tiếp với nệm, không cần box spring\nKích thước thanh giường: Rộng 167.64 cm × cao 6.99 cm\nKhoảng hở từ sàn đến bệ giường: 13.34 cm\nKích thước bệ giường: Rộng 162.56 cm × sâu 210.82 cm × cao 15.24 cm\nKệ trên hai bên: Rộng 45.72 cm × sâu 20.32 cm\nKệ dưới hai bên: Rộng 45.72 cm × sâu 35.56 cm\nKhoảng cách giữa hai kệ: 25.40 cm\nKhoảng cách từ sàn đến mặt trên của kệ: 43.82 cm\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm khô; không dùng chất tẩy rửa có tính mài mòn; không để chất lỏng đọng lâu; tránh nhiệt và chất lỏng; có thể phai màu nhẹ dưới ánh nắng trực tiếp; nên dùng miếng lót và lau ngay khi chất lỏng bị đổ"}', 80.0, 210.82, 254.0, 50.0, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('df66c802-87aa-6ee7-389a-341b9f576b10', '0f1009d0-7040-f0e0-8a49-15c9a15aa1ad', 'Ghế bành da Loop màu nâu chocolate', 'ghe-banh-da-loop-mau-nau-chocolate', 'AC-LOOP', 'Ghế bành Loop do Andreas Hansen thiết kế, nổi bật với khung sắt uốn cong hoàn thiện niken đánh bóng và phần tay vịn bọc da. Sản phẩm sử dụng da nguyên hạt màu nâu chocolate với sắc độ tự nhiên, kết hợp mặt ngồi và tựa lưng cố định sử dụng mút mật độ cao. Kiểu dáng mang cảm hứng hiện đại Đan Mạch, phù hợp làm ghế điểm nhấn trong phòng khách hoặc góc đọc sách.', 'ACTIVE', 44683700.0, '["\"Thiết kế độc quyền bởi Andreas Hansen\",", "\"Bọc da thật full-grain nhuộm aniline\",", "\"Khung sắt hoàn thiện niken đánh bóng\",", "\"Chi tiết tay ghế được quấn da\",", "\"Đệm ngồi và tựa lưng cố định bằng mút mật độ cao\",", "\"Miếng lót dưới chân giúp hạn chế làm trầy sàn\",", "\"Phong cách hiện đại Đan Mạch\""]', '{"details": "Chất liệu khung: Sắt hoàn thiện niken đánh bóng\nChất liệu bọc: Da thật full-grain nhuộm aniline\nChất liệu đệm: Mút mật độ cao\nChiều cao tay vịn: 55.88, cm\nChiều cao mặt ngồi: 36.20, cm\nĐộ sâu mặt ngồi: 49.83, cm\nChiều rộng mặt ngồi: 61.60, cm\nNhà thiết kế: Andreas Hansen\nXuất xứ: Đài Loan\nHướng dẫn bảo quản: Hút bụi hoặc chải nhẹ để loại bỏ bụi bẩn"}', 20.85, 87.93, 70.15, 63.5, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('6e6900d0-6ef7-d0f2-d9d0-4540f59ef6c6', '16bc894b-0e9b-583e-ad23-dafb43200b62', 'Bàn phụ Koa', 'ban-phu-koa', 'ST-KOA', 'Bàn phụ Koa do Evan Jerry của Studio ANANSI thiết kế, nổi bật với kiểu dáng điêu khắc mềm mại, các khoảng rỗng và đường cong cân đối. Sản phẩm có ba lựa chọn vật liệu gồm nhựa resin vân đá màu nâu, nhựa resin vân đá màu xám và gỗ Acacia nguyên khối. Kiểu dáng nhỏ gọn phù hợp đặt cạnh sofa, ghế bành hoặc sử dụng như một điểm nhấn trang trí trong phòng khách.', 'ACTIVE', 9178700.0, '["\"Thiết kế độc quyền bởi Evan Jerry của Studio ANANSI\",", "\"Kiểu dáng điêu khắc với đường cong mềm mại và khoảng rỗng\",", "\"Thiết kế nhỏ gọn, phù hợp đặt cạnh sofa hoặc ghế bành\",", "\"Có ba lựa chọn vật liệu và hoàn thiện bề mặt\",", "\"Mỗi sản phẩm có hoa văn, sắc độ hoặc vân vật liệu riêng\",", "\"Phù hợp với không gian phòng khách hiện đại\""]', '{"details": "Nhà thiết kế: Evan Jerry của Studio ANANSI\nLoại sản phẩm: Bàn phụ\nVị trí sử dụng: Cạnh sofa, ghế bành hoặc khu vực trang trí"}', NULL, 34.29, 43.18, 48.26, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('9dbad847-7a4b-91d4-02e4-27d29209918b', 'b5abeb51-d655-c2dd-b795-c35e6b9a3c8f', 'Bàn console Bodene 82 inch', 'ban-console-bodene-82-inch', 'CT-BODENE', 'Bàn console Bodene 82 inch do VUUE thiết kế, nổi bật với dáng hình hữu cơ và bề mặt uốn lượn gợi cảm giác được tạo hình thủ công. Kết cấu nhựa resin composite đúc mang đến vẻ đẹp điêu khắc mang tinh thần hậu hiện đại. Sản phẩm có hai lựa chọn hoàn thiện màu đen mờ và ngà voi mờ, phù hợp đặt sát tường, sau sofa hoặc tại khu vực lối vào của phòng khách.', 'ACTIVE', 33637700.0, '["\"Thiết kế độc quyền bởi VUUE\",", "\"Kiểu dáng điêu khắc mang phong cách hậu hiện đại\",", "\"Dáng hình hữu cơ với bề mặt uốn lượn độc đáo\",", "\"Kết cấu nhựa resin composite đúc chắc chắn\",", "\"Có hai lựa chọn hoàn thiện màu đen mờ và ngà voi mờ\",", "\"Phù hợp đặt sát tường, sau sofa hoặc tại khu vực lối vào\",", "\"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: VUUE\nPhong cách: Hậu hiện đại\nChất liệu: Nhựa resin composite đúc\nKiểu hoàn thiện: Bề mặt mờ\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm khô; không sử dụng chất tẩy rửa có tính mài mòn; không để chất lỏng đọng lâu; nên dùng miếng lót ly và lau ngay khi chất lỏng bị đổ"}', 59.95, 40.64, 209.55, 76.2, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('1bce105b-f293-9d1e-7701-7e7da8f057c3', '16bc894b-0e9b-583e-ad23-dafb43200b62', 'Bàn phụ đá cẩm thạch I Beam', 'ban-phu-da-cam-thach-i-beam', 'ST-IBEAM', 'Bàn phụ I Beam lấy cảm hứng từ kiến trúc hiện đại và phong cách công nghiệp, nổi bật với cấu trúc hình chữ I mạnh mẽ. Các tấm đá cẩm thạch được cắt theo hình, ghép nối và hoàn thiện thủ công, tạo nên một món nội thất nhỏ gọn nhưng có điểm nhấn rõ rệt. Sản phẩm phù hợp đặt cạnh sofa hoặc ghế bành để đặt sách, đồ uống và các vật dụng trang trí.', 'ACTIVE', 10493700.0, '["\"Thiết kế lấy cảm hứng từ kiến trúc hiện đại và phong cách công nghiệp\",", "\"Kiểu dáng chữ I tạo điểm nhấn hình học mạnh mẽ\",", "\"Các tấm đá cẩm thạch được cắt, ghép và hoàn thiện thủ công\",", "\"Mỗi sản phẩm có sắc độ và đường vân đá tự nhiên riêng\",", "\"Kích thước nhỏ gọn, phù hợp đặt cạnh sofa hoặc ghế bành\",", "\"Sản xuất tại Ấn Độ\""]', '{"details": "Kiểu dáng: Hình chữ I\nPhương pháp hoàn thiện: Cắt, ghép và hoàn thiện thủ công\nĐặc điểm vật liệu: Sắc độ và đường vân tự nhiên khác nhau trên từng sản phẩm\nXuất xứ: Ấn Độ\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm khô; không sử dụng chất tẩy rửa có tính mài mòn; không để chất lỏng đọng lâu; nên dùng miếng lót ly; lau ngay chất lỏng bị đổ để hạn chế vết ố và vệt nước"}', 29.48, 30.48, 38.1, 50.8, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('3a9d6259-b579-a4a1-401c-9d79b87146fd', '0f1009d0-7040-f0e0-8a49-15c9a15aa1ad', 'Ghế bành Thomas lưng đan mây', 'ghe-banh-thomas-lung-dan-may', 'AC-THOMAS', 'Ghế bành Thomas lưng đan mây do Paul McCobb thiết kế, tái hiện kiểu dáng giữa thế kỷ 20 với đường nét góc cạnh, khung gỗ sồi tối màu và phần lưng đan mây tạo điểm nhấn tự nhiên. Đệm rời sử dụng mút mật độ cao, được bọc hỗn hợp lông vũ và sợi polyester để cân bằng độ êm ái và khả năng nâng đỡ. Sản phẩm phù hợp làm ghế điểm nhấn trong phòng khách, góc đọc sách hoặc khu vực thư giãn.', 'ACTIVE', 16542700.0, '["\"Thiết kế biểu tượng giữa thế kỷ 20 bởi Paul McCobb\",", "\"Khung gỗ sồi đạt chứng nhận quản lý rừng bền vững FSC\",", "\"Các góc khung được gia cố nhằm tăng độ chắc chắn\",", "\"Lưng ghế đan mây tạo điểm nhấn tự nhiên\",", "\"Chân ghế bằng gỗ sồi nguyên khối hoàn thiện màu tối\",", "\"Đệm rời sử dụng mút mật độ cao, kết hợp lông vũ và sợi polyester\",", "\"Có hai lựa chọn chất liệu bọc phù hợp với nhiều phong cách phòng khách\""]', '{"details": "Nhà thiết kế: Paul McCobb\nPhong cách: Hiện đại giữa thế kỷ 20\nChất liệu khung: Gỗ sồi đạt chứng nhận FSC\nKết cấu khung: Gia cố bằng liên kết chặn góc\nChất liệu lưng ghế: Mây đan\nChất liệu chân ghế: Gỗ sồi nguyên khối\nHoàn thiện khung: Màu gỗ tối\nKích thước đệm: Rộng 53.98 cm × sâu 53.98 cm × dày 8.89 cm\nChiều cao chân ghế: 33.66 cm\nChiều cao tay vịn: 58.12 cm\nKhối lượng: Không có thông tin từ nhà cung cấp\nHướng dẫn bảo quản: Thấm hút ngay khi chất lỏng bị đổ; không dùng chất tẩy rửa có tính mài mòn; tránh nhiệt, chất lỏng và ánh nắng trực tiếp; nên sử dụng dịch vụ vệ sinh chuyên nghiệp đối với phần bọc"}', NULL, 67.95, 60.96, 89.54, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('7f9b277c-74f0-426c-2adf-710fcb9d5966', '40abee88-08e0-2eb3-6322-2a378cc12436', 'Chậu cây thông mini giả', 'chau-cay-thong-mini-gia', 'DEC-PINE-PLANT', 'Chậu cây thông mini giả mô phỏng sắc xanh tươi và dáng điêu khắc tự nhiên của cây mọng nước. Sản phẩm được đặt trong chậu polyresin màu trắng có bề mặt nhẵn, phù hợp trang trí bàn làm việc, kệ tủ, bàn console hoặc các góc nhỏ trong phòng khách. Thiết kế cây giả giúp duy trì vẻ đẹp ổn định mà không cần tưới nước hay chăm sóc thường xuyên.', 'ACTIVE', 1314211.0, '["\"Mô phỏng màu sắc và kiểu dáng tự nhiên của cây mọng nước\",", "\"Thiết kế dạng cây thông mini tạo điểm nhấn điêu khắc\",", "\"Chậu polyresin màu trắng với bề mặt nhẵn\",", "\"Thành phần nhựa chứa 50% vật liệu tái chế\",", "\"Không cần tưới nước hoặc chăm sóc thường xuyên\",", "\"Phù hợp trang trí bàn làm việc, kệ tủ và không gian phòng khách\""]', '{"details": "Loại sản phẩm: Cây trang trí giả\nKiểu cây: Cây mọng nước dạng thông mini\nChất liệu cây: Nhựa, chứa 50% nhựa tái chế\nChất liệu chậu: Nhựa polyresin\nMàu chậu: Trắng\nKhối lượng: Không có thông tin từ nhà cung cấp\nXuất xứ: Nhập khẩu\nHướng dẫn bảo quản: Lau sạch bằng khăn mềm"}', NULL, 35.99, 35.99, 43.0, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('fdfeacf2-2d84-6f40-2214-0b7fa98b6e79', '45ee3b7d-83b4-294b-fce1-7e855b62cf96', 'Tủ đầu giường Shagreen 24 inch hai ngăn kéo', 'tu-dau-giuong-shagreen-24-inch-hai-ngan-keo', 'NS-SHAGREEN', 'Tủ đầu giường Shagreen 24 inch do Amanda Ip của Slate Design thiết kế, nổi bật với toàn bộ thân tủ được bọc thủ công bằng vật liệu giả da cá đuối dập nổi màu trắng ấm. Khung kim loại mảnh hoàn thiện màu đồng thau tạo cảm giác nhẹ và sang trọng, trong khi hai ngăn kéo sâu sử dụng ray trượt kim loại và tay nắm đồng bộ giúp tăng khả năng lưu trữ bên cạnh giường.', 'ACTIVE', 18383700.0, '["\"Thiết kế độc quyền bởi Amanda Ip của Slate Design\",", "\"Thân tủ được bọc thủ công bằng vật liệu giả da cá đuối dập nổi\",", "\"Khung kim loại mảnh hoàn thiện màu đồng thau\",", "\"Hai ngăn kéo sâu sử dụng ray trượt kim loại\",", "\"Tay nắm sắt hoàn thiện màu đồng thau\",", "\"Kiểu dáng hiện đại, phù hợp không gian phòng ngủ sang trọng\",", "\"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: Amanda Ip của Slate Design\nPhương pháp chế tác: Thủ công\nChất liệu khung tủ: Gỗ kỹ thuật bọc PVC giả da cá đuối dập nổi\nChất liệu chân đế: Khung kim loại hoàn thiện màu đồng thau\nNgăn kéo: Hai ngăn kéo sâu, ray trượt kim loại\nPhụ kiện: Núm kéo bằng sắt hoàn thiện màu đồng thau\nKích thước chân đế kim loại: Rộng 59.69 cm × sâu 39.37 cm × cao 12.70 cm\nKích thước trong ngăn kéo: Rộng 50.17 cm × sâu 27.31 cm × cao 11.43 cm\nKhoảng hở dưới tủ: 8.89 cm\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Lau sạch bằng khăn mềm khô"}', 35.79, 40.64, 59.69, 54.61, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('0efb0ecc-7481-cd21-989f-39e6fa4e55dd', '45ee3b7d-83b4-294b-fce1-7e855b62cf96', 'Tủ đầu giường Archer 22 inch một ngăn kéo', 'tu-dau-giuong-archer-22-inch-mot-ngan-keo', 'NS-ARCHER', 'Tủ đầu giường Archer 22 inch do VUUE thiết kế, sở hữu đường cong mềm mại và bề mặt phủ linen tự nhiên trên cốt gỗ kỹ thuật. Lớp sơn mài bảo vệ kết hợp hiệu ứng wash xám tạo chiều sâu cho màu trắng, trong khi ngăn kéo đơn với tay nắm acrylic trong suốt mang lại vẻ hiện đại và tinh tế cho không gian phòng ngủ.', 'ACTIVE', 9178700.0, '["\"Thiết kế độc quyền bởi VUUE\",", "\"Kiểu dáng bo cong mềm mại\",", "\"Bề mặt phủ linen tự nhiên trên gỗ kỹ thuật\",", "\"Lớp sơn mài bảo vệ kết hợp hiệu ứng wash xám\",", "\"Một ngăn kéo với tay nắm acrylic trong suốt\",", "\"Đạt tiêu chuẩn sử dụng nội thất thương mại\",", "\"Sản xuất tại Việt Nam\""]', '{"details": "Nhà thiết kế: VUUE\nChất liệu khung: Gỗ kỹ thuật phủ linen tự nhiên\nHoàn thiện bề mặt: Sơn mài bảo vệ kết hợp lớp wash xám\nNgăn kéo: Một ngăn kéo\nPhụ kiện: Núm kéo acrylic trong suốt\nCấp độ sử dụng: Đạt tiêu chuẩn nội thất thương mại\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm khô; không để chất lỏng đọng lâu; không dùng chất tẩy rửa có tính mài mòn; thấm hút ngay vết đổ bằng khăn trắng sạch; tránh nhiệt và chất lỏng; có thể phai màu nhẹ dưới ánh nắng trực tiếp; không sử dụng sáp hoặc chất đánh bóng"}', 23.86, 45.72, 55.88, 53.34, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('00694f9f-53ca-3ddf-ca05-6353651695a0', '18b69b70-6d60-230a-bf07-7b0261a4eea7', 'Ghế băng bọc lông cừu Socca', 'ghe-bang-boc-long-cuu-socca', 'BN-SOCCA', 'Ghế băng bọc lông cừu Socca do Gonçalo Campos thiết kế, kết hợp đế gỗ walnut tông ấm với phần đệm bọc lông cừu Mông Cổ màu taupe mềm mại. Kiểu dáng dài, thấp và giàu chất liệu giúp sản phẩm phù hợp đặt cuối giường, tại góc thay đồ hoặc khu vực chuyển tiếp trong phòng ngủ. Sản phẩm có hai kích thước 55 inch và 67 inch.', 'ACTIVE', 47313700.0, '["\"Thiết kế độc quyền bởi Gonçalo Campos\",", "\"Đế gỗ walnut đạt chứng nhận FSC\",", "\"Bọc 100% lông cừu Mông Cổ màu taupe có nguồn cung ứng nhân đạo\",", "\"Kiểu dáng mềm mại, tăng chất cảm cho không gian phòng ngủ\",", "\"Phù hợp đặt cuối giường, góc thay đồ hoặc khu vực chuyển tiếp\",", "\"Có hai lựa chọn kích thước 55 inch và 67 inch\",", "\"Sản xuất tại nhiều quốc gia\""]', '{"details": "Nhà thiết kế: Gonçalo Campos\nKích thước: 55 inch\nChất liệu đế: Gỗ walnut và veneer walnut đạt chứng nhận FSC\nChất liệu bọc: 100% lông cừu Mông Cổ màu taupe, nguồn cung ứng nhân đạo\nKhoảng cách giữa hai chân: 89.54 cm\nKhoảng hở dưới ghế: 20.32 cm\nXuất xứ: Nhiều quốc gia\nHướng dẫn bảo quản: Làm theo nhãn hướng dẫn trên sản phẩm; kích thước bọc thủ công có thể sai lệch nhẹ; hút bụi và xoay đệm định kỳ; tránh ánh nắng trực tiếp; nên vệ sinh bằng dịch vụ bọc ghế chuyên nghiệp; chỉ chải nhẹ hoặc hút bụi phần vải"}', 21.45, 48.26, 139.7, 41.91, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('d1f61d6a-9fb6-b881-8879-79dba27ca5b0', '9f78ae93-d859-0893-bd85-58d2d1f34c43', 'Giường canopy Amani bọc vải khung thép rèn thủ công', 'giuong-canopy-amani-boc-vai-khung-thep-ren-thu-cong', 'BED-AMANI', 'Giường canopy Amani do Mermelada Estudio thiết kế, nổi bật với bốn trụ thép đặc được rèn và xoắn thủ công khi kim loại còn nóng. Những biến đổi nhẹ trên từng trụ tạo nên vẻ thủ công riêng biệt, trong khi đầu giường và cuối giường được đệm dày, bọc vải màu trắng ấm để cân bằng cảm giác mạnh mẽ của khung kim loại. Sản phẩm có hai kích thước Queen và King, phù hợp với phòng ngủ hiện đại sang trọng.', 'ACTIVE', 52573700.0, '["\"Thiết kế độc quyền bởi Mermelada Estudio\",", "\"Bốn trụ thép đặc được rèn và xoắn thủ công\",", "\"Khung gỗ kỹ thuật nguyên khối có độ bền cao\",", "\"Đầu giường và cuối giường được bọc đệm toàn bộ\",", "\"Đệm polyfoam dày mang lại cảm giác êm ái\",", "\"Vải màu trắng ấm Snow tạo vẻ thanh lịch\",", "\"Có hai lựa chọn kích thước Queen và King\",", "\"Sản xuất tại Ấn Độ\""]', '{"details": "Nhà thiết kế: Mermelada Estudio\nKích thước: Queen\nKiểu giường: Canopy bốn trụ\nChất liệu trụ: Thép đặc rèn và xoắn thủ công\nChất liệu khung: Gỗ kỹ thuật nguyên khối\nChất liệu bọc: Vải boucle poly-acrylic màu trắng ấm\nCấu tạo đệm: Mút polyfoam\nYêu cầu sử dụng: Dùng trực tiếp với nệm, không cần box spring\nKhoảng hở dưới thanh giường: 26.04 cm\nKhoảng cách giữa các thanh giường: 1.91 cm\nKích thước thanh giường: Rộng 76.20 cm × sâu 10.16 cm\nChiều cao thành giường: 9.53 cm\nChiều cao cuối giường: 36.83 cm\nKhoang đặt nệm: Rộng 154.94 cm × sâu 210.82 cm\nXuất xứ: Ấn Độ\nHướng dẫn bảo quản: Không để vết đổ lưu lại; tránh ánh nắng trực tiếp; thấm hút ngay bằng khăn trắng sạch; không dùng chất tẩy rửa có tính mài mòn; hút bụi bằng đầu hút bọc ghế; vệ sinh điểm bằng khăn ẩm và chất tẩy nhẹ; với vết bẩn cứng đầu nên sử dụng dịch vụ vệ sinh chuyên nghiệp"}', 198.67, 215.90, 160.02, 213.36, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('1f80df20-1ef6-c699-ffab-7e6fe268f60b', '1d159325-75ed-eb7d-4028-166180fcaa43', 'Kệ lưu trữ phòng tắm Athena', 'ke-luu-tru-phong-tam-athena', 'BATH-ATHENA', 'Kệ lưu trữ Athena do Mermelada Estudio thiết kế, kết hợp khung thép không gỉ đánh bóng với bốn kệ kính gân cố định. Thiết kế lưng mở tạo cảm giác nhẹ và thoáng, trong khi dáng kệ đứng nhỏ gọn giúp sắp xếp khăn tay, mỹ phẩm và các vật dụng thiết yếu mà không chiếm nhiều diện tích phòng tắm.', 'INACTIVE', NULL, '["\"Thiết kế độc quyền bởi Mermelada Estudio\",", "\"Khung thép không gỉ đánh bóng hiện đại\",", "\"Thiết kế lưng mở tạo cảm giác thông thoáng\",", "\"Bốn kệ kính gân cố định\",", "\"Dáng đứng nhỏ gọn, tận dụng không gian theo chiều cao\",", "\"Phù hợp lưu trữ khăn tay, mỹ phẩm và đồ dùng phòng tắm\""]', '{"details": "Nhà thiết kế: Mermelada Estudio\nChất liệu khung: Thép không gỉ đánh bóng\nChất liệu kệ: Kính gân trong suốt\nSố kệ: 4 kệ cố định\nKiểu lưng: Lưng mở\nTình trạng nguồn: Sản phẩm không còn được CB2 bán\nGiá bán: Không còn hiển thị trên nguồn\nKhối lượng: Không có thông tin từ nhà cung cấp\nHướng dẫn bảo quản: Lau bằng khăn mềm; không dùng chất tẩy rửa có tính mài mòn"}', NULL, 30.3, 30.3, 76.2, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('3688826c-32f6-afbc-4d4d-056d39ed50ea', '45e193fd-9db3-2a16-e4d3-1b9191568844', 'Giỏ đựng đồ giặt Shagreen', 'gio-dung-do-giat-shagreen', 'BATH-HAMPER-SHAGREEN', 'Giỏ đựng đồ giặt Shagreen có khung gỗ kỹ thuật bọc vật liệu giả da cá đuối dập nổi, tạo bề mặt sần đặc trưng lấy cảm hứng từ phong cách Art Deco. Nắp bản lề giúp che quần áo bên trong, trong khi túi vải pha polyester và cotton có dây rút, có thể tháo rời để thuận tiện khi mang đồ đi giặt. Sản phẩm có hai màu Ivory và Grey.', 'ACTIVE', 4812900.0, '["\"Bề mặt giả da cá đuối dập nổi mang phong cách Art Deco\",", "\"Khung gỗ kỹ thuật chắc chắn\",", "\"Nắp bản lề giúp che quần áo bên trong\",", "\"Túi vải bên trong có dây rút và có thể tháo rời\",", "\"Tay cầm mở giúp tăng khả năng thông khí\",", "\"Có hai lựa chọn màu Ivory và Grey\",", "\"Không dành cho tải trọng lớn hoặc sử dụng nặng\""]', '{"details": "Chất liệu khung: Gỗ kỹ thuật\nChất liệu bề mặt: Polyester và PU giả da cá đuối dập nổi\nChất liệu túi bên trong: Hỗn hợp polyester và cotton\nKiểu nắp: Nắp bản lề\nTúi bên trong: Có dây rút, có thể tháo rời\nPhạm vi sử dụng: Không dành cho tải trọng lớn hoặc sử dụng nặng\nKhối lượng: Không có thông tin từ nhà cung cấp\nXuất xứ: Nhập khẩu"}', NULL, 30.48, 53.34, 60.96, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('f3a5dd40-0c59-aaf0-a6b9-9299c616eba9', 'f771c92b-b11a-f2f6-90c3-78b8e25b2539', 'Giá treo khăn đôi Dois', 'gia-treo-khan-doi-dois', 'BATH-TOWEL-DOIS', 'Giá treo khăn đôi Dois do Mermelada Estudio thiết kế, sử dụng khung thép không gỉ với đường nét tối giản và hai thanh treo đặt ở hai độ cao khác nhau. Thiết kế đứng độc lập giúp tối ưu không gian phòng tắm mà không cần khoan tường. Sản phẩm có ba lựa chọn hoàn thiện: nickel bóng, đồng thau satin và đen mờ.', 'ACTIVE', 3313800.0, '["\"Thiết kế độc quyền bởi Mermelada Estudio\",", "\"Khung thép không gỉ với đường nét tối giản\",", "\"Hai tầng treo khăn ở hai độ cao khác nhau\",", "\"Thiết kế đứng độc lập, không cần lắp cố định lên tường\",", "\"Có ba lựa chọn hoàn thiện nickel bóng, đồng thau satin và đen mờ\",", "\"Sản xuất tại Ấn Độ\""]', '{"details": "Nhà thiết kế: Mermelada Estudio\nChất liệu chính: Thép không gỉ\nSố thanh treo: 2\nChiều cao thanh dưới: 59.05 cm\nChiều cao thanh trên: 81.28 cm\nKiểu lắp đặt: Đứng độc lập\nKhối lượng: Không có thông tin từ nhà cung cấp\nXuất xứ: Ấn Độ\nHướng dẫn bảo quản: Lau bằng khăn mềm; không dùng chất tẩy rửa có tính mài mòn"}', NULL, 20.32, 40.64, 81.28, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('b8129c0f-28bf-f3e2-a04e-54558cc411e7', '5cb87d5b-6675-31f5-4dba-afed822645a2', 'Giỏ lưu trữ đan Aminah tay cầm đen', 'gio-luu-tru-dan-aminah-tay-cam-den', 'BATH-BASKET-AMINAH', 'Giỏ lưu trữ đan Aminah do nghệ sĩ và nhà thiết kế Élan Byrd sáng tạo cho Black in Design Collective. Sản phẩm được đan thủ công từ vỏ chuối tự nhiên, mây và cỏ biển, kết hợp tay cầm cùng các đường sọc màu đen tương phản. Kiểu dáng hữu cơ giúp giỏ phù hợp để đựng khăn, đồ dùng phòng tắm hoặc làm chậu bọc ngoài cho cây cảnh. Sản phẩm có hai kích thước Small và Large.', 'ACTIVE', 2628685.0, '["\"Thiết kế bởi Élan Byrd cho Black in Design Collective\",", "\"Đan thủ công từ vật liệu tự nhiên\",", "\"Kết hợp vỏ chuối, mây và cỏ biển\",", "\"Tay cầm và sọc màu đen tạo độ tương phản\",", "\"Có thể dùng để lưu trữ khăn và đồ dùng phòng tắm\",", "\"Bản Large có thể dùng làm chậu bọc ngoài cho cây cảnh\",", "\"Có hai kích thước Small và Large\",", "\"Sản xuất tại Indonesia\""]', '{"details": "Nhà thiết kế: Élan Byrd\nBộ sưu tập: Black in Design Collective\nPhương pháp chế tác: Đan thủ công\nChất liệu: Lá chuối, mây và cỏ biển\nMàu sắc: Tự nhiên phối tay cầm và sọc đen\nSố lựa chọn kích thước: 2\nKhối lượng: Không có thông tin từ nhà cung cấp\nXuất xứ: Indonesia\nHướng dẫn bảo quản: Lau bụi bằng khăn mềm; không dùng chất tẩy rửa mạnh hoặc có tính mài mòn"}', NULL, NULL, NULL, NULL, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, category_id, name, slug, sku, description, product_status, base_price, features, specifications, weight, length, width, height, sold_count, rating, rating_count, created_at, updated_at) VALUES ('559c0e59-f84e-1d05-df27-676a8c3c0d9b', '698bddc8-062b-53a8-90fb-843da9f8b89a', 'Giá đỡ cuộn giấy lau acrylic', 'gia-do-cuon-giay-lau-acrylic', 'BATH-PAPER-ACRYLIC', 'Giá đỡ cuộn giấy lau bằng acrylic được chế tác thủ công với thiết kế trong suốt, tối giản và nhẹ về thị giác. Kiểu dáng nhỏ gọn giúp sản phẩm dễ đặt trên mặt bàn, kệ hoặc cạnh bồn rửa để giữ cuộn giấy lau tay gọn gàng mà không làm nặng không gian.', 'ACTIVE', 1182185.0, '["\"Chế tác thủ công từ acrylic trong suốt\",", "\"Thiết kế tối giản, nhẹ về thị giác\",", "\"Dáng trụ tròn nhỏ gọn, dễ bố trí trên mặt bàn\",", "\"Phù hợp giữ cuộn giấy lau tay hoặc giấy lau đa năng\",", "\"Dễ vệ sinh bằng khăn ẩm sạch\",", "\"Sản xuất tại Đài Loan\""]', '{"details": "Chất liệu: Acrylic\nPhương pháp chế tác: Thủ công\nHình dạng: Trụ tròn\nĐường kính: 17.14 cm\nChiều cao: 33.02 cm\nKhối lượng: Không có thông tin từ nhà cung cấp\nXuất xứ: Đài Loan\nHướng dẫn bảo quản: Lau bằng khăn sạch và ẩm"}', NULL, 17.14, 17.14, 33.02, 0, 0.0, 0, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_variants (id, product_id, sku, price, stock_quantity, low_stock_threshold, weight, length, width, height, material, warranty, color, model_url, supports_3d, specifications, created_at, updated_at) VALUES ('27ca9cce-2516-39eb-72c1-d2b05099c859', 'fd342f1c-932d-1693-4cd9-13d2ac1ca354', 'DC-NOR-001', NULL, 100.0, 5.0, 6.49,  48.90,  62.23,  78.74,  'Vải nhung pha cotton Luca', NULL, 'Tím lilac đậm', '/models/model_43.glb', True, '{"details": "Nhà thiết kế: Caleb Zipperer\nLoại sản phẩm: Ghế ăn không tay vịn\nChất liệu khung: Gỗ sồi đỏ đạt chứng nhận FSC\nKết cấu khung: Gỗ được tiện tạo đường nét thanh mảnh\nChi tiết hoàn thiện: Màu đồng thau\nCấu tạo đệm: Mút mật độ cao\nĐặc điểm vật liệu: Sắc độ, mắt gỗ và dấu vân tự nhiên khác nhau trên từng sản phẩm\nXuất xứ: Việt Nam\nHướng dẫn bảo quản: Thấm hút ngay khi chất lỏng bị đổ bằng khăn sạch; chỉ vệ sinh điểm bằng chất tẩy vết bẩn không chứa nước; với vết bẩn cứng đầu nên sử dụng dịch vụ vệ sinh bọc ghế chuyên nghiệp"}', NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
